import numpy as np
import torch
from monai.data import list_data_collate

# case 1: mixed tensor/numpy per key -> TypeError with key
a = {"image": torch.rand(3, 3), "label": torch.rand(4, 4)}
b = {"image": np.zeros((3, 3)), "label": torch.rand(4, 4)}
try:
    list_data_collate([a, b])
except TypeError as e:
    print("TypeError:", e)

# case 2: inconsistent shapes -> RuntimeError with key
c = {"image": torch.rand(3, 3), "label": torch.rand(4, 4)}
d = {"image": torch.rand(3, 3), "label": torch.rand(5, 5)}
try:
    list_data_collate([c, d])
except RuntimeError as e:
    print("RuntimeError:", e)

# case 3: non-dict failure (no key reported, hint still added)
try:
    list_data_collate([torch.rand(3, 3), torch.rand(4, 4)])
except RuntimeError as e:
    print("RuntimeError (no key):", e)

# case 4: normal dict collation still works
r = list_data_collate([{"image": np.ones((2, 2)), "label": 1}, {"image": np.zeros((2, 2)), "label": 2}])
print("ok:", type(r), r["image"].shape, r["label"])

# case 5: list-of-list-of-dict flattening still works
e = {"image": np.array([1, 2, 3]), "label": np.array([4, 5, 6])}
r = list_data_collate([[e, e], [e, e]])
print("ok:", r["image"].shape)

# case 6: other TypeError without numpy/Tensor passes through unchanged
class Weird: pass
try:
    list_data_collate([{"x": Weird()}, {"x": Weird()}])
except Exception as e:
    print("passthrough:", type(e).__name__, e)
